//! Scratch-only independent numerical checks for the f32-I/O/f64 adapter.
use rustsht::{Complex32,Complex64,GridKind,GridSpec,HarmonicSpec,ShtPlan};
use std::f64::consts::{PI,TAU};
fn close(x:f64,y:f64,tol:f64,label:&str){let e=(x-y).abs()/x.abs().max(y.abs()).max(1e-12);assert!(e<=tol,"{label}: {x} vs {y}, rel={e}")}
fn coeffs(spec:&HarmonicSpec)->Vec<Complex32>{let mut a=vec![Complex32::new(0.0,0.0);spec.nalm()];for(l,m,v)in[(0,0,Complex32::new(0.7,0.)),(1,0,Complex32::new(-0.2,0.)),(2,0,Complex32::new(0.1,0.)),(1,1,Complex32::new(0.4,0.3)),(2,1,Complex32::new(-0.2,0.15)),(2,2,Complex32::new(0.1,-0.6))]{if let Some(i)=spec.index(l,m){a[i]=v}}a}
fn to64c(a:&[Complex32])->Vec<Complex64>{a.iter().map(|x|Complex64::new(x.re as f64,x.im as f64)).collect()}
fn narrowc(a:&[Complex64])->Vec<Complex32>{a.iter().map(|x|Complex32::new(x.re as f32,x.im as f32)).collect()}
fn map_inner(a:&[f32],b:&[f32])->f64{a.iter().zip(b).map(|(&x,&y)|x as f64*y as f64).sum()}
fn coeff_inner(spec:&HarmonicSpec,a:&[Complex32],b:&[Complex32])->f64{let mut s=0.;for m in 0..=spec.mmax(){let w=if m==0{1.}else{2.};for l in m..=spec.lmax(){let i=spec.index(l,m).unwrap();s+=w*((a[i].re as f64)*(b[i].re as f64)+(a[i].im as f64)*(b[i].im as f64));}}s}
fn main(){
 let qset=[std::env::args().nth(1).expect("q1 or q8").parse::<usize>().unwrap()];
 for q in qset{rayon::ThreadPoolBuilder::new().num_threads(q).build_global().unwrap_or_else(|_|panic!("run each q in a fresh process"));for mmax in [180,720]{let np=if mmax==180{378}else{1458};let lmax=720;let nt=721;let phi0=0.23;let p64=ShtPlan::<f64>::new(GridSpec::new(GridKind::GaussLegendre,nt,np,phi0).unwrap(),HarmonicSpec::scalar(lmax,mmax).unwrap()).unwrap();let p32=ShtPlan::<f32>::new(GridSpec::new(GridKind::GaussLegendre,nt,np,phi0).unwrap(),HarmonicSpec::scalar(lmax,mmax).unwrap()).unwrap();let mut w64=p64.workspace().unwrap();p64.prepare_workspace(&mut w64,q).unwrap();let mut w32=p32.workspace().unwrap();p32.prepare_workspace(&mut w32,q).unwrap();let spec=p64.harmonics();let a32=coeffs(spec);let a64=to64c(&a32);let mut map64=vec![f64::NAN;nt*np];p64.synthesis_into(&a64,&mut map64,&mut w64).unwrap();let map32=map64.iter().map(|x|*x as f32).collect::<Vec<_>>();
  let y00=1./(4.*PI).sqrt();let c11=a32[spec.index(1,1).unwrap()];let c21=a32[spec.index(2,1).unwrap()];let c22=a32[spec.index(2,2).unwrap()];let mut diff=0.;let mut norm=0.;let mut max=0_f64;let mut i=0;for &theta in p64.grid().theta(){let(st,ct)=theta.sin_cos();let y10=(3./(4.*PI)).sqrt()*ct;let y20=(5./(16.*PI)).sqrt()*(3.*ct*ct-1.);let y11=-(3./(8.*PI)).sqrt()*st;let y21=-(15./(8.*PI)).sqrt()*st*ct;let y22=(15./(32.*PI)).sqrt()*st*st;for j in 0..np{let phi=phi0+TAU*j as f64/np as f64;let x=a32[spec.index(0,0).unwrap()].re as f64*y00+a32[spec.index(1,0).unwrap()].re as f64*y10+a32[spec.index(2,0).unwrap()].re as f64*y20+2.*(c11.re as f64*y11*phi.cos()-c11.im as f64*y11*phi.sin())+2.*(c21.re as f64*y21*phi.cos()-c21.im as f64*y21*phi.sin())+2.*(c22.re as f64*y22*(2.*phi).cos()-c22.im as f64*y22*(2.*phi).sin());let d=map32[i] as f64-x;diff+=d*d;norm+=x*x;max=max.max(d.abs());i+=1;}}
  let rel=(diff/norm).sqrt();assert!(rel<2e-5&&max<2e-5,"scalar synthesis analytic T720 m={mmax} q={q}: {rel} {max}");let first=map32.clone();map64.fill(f64::NAN);p64.synthesis_into(&a64,&mut map64,&mut w64).unwrap();let again=map64.iter().map(|x|*x as f32).collect::<Vec<_>>();assert!(first.iter().zip(&again).all(|(x,y)|x.to_bits()==y.to_bits()),"workspace reset");
  let testmap=(0..nt*np).map(|i|{let i=i as f32;(i*0.000173).sin()+0.2*(i*0.000071).cos()}).collect::<Vec<_>>();let mut adj=vec![Complex32::new(0.,0.);spec.nalm()];p32.adjoint_synthesis_into(&testmap,&mut adj,&mut w32).unwrap();close(map_inner(&map32,&testmap),coeff_inner(spec,&a32,&adj),2e-4,"scalar synthesis adjoint");
  if mmax==720{let mut sector=vec![Complex64::new(0.,0.);spec.nalm()];sector[spec.index(720,720).unwrap()]=Complex64::new(1.,0.);p64.synthesis_into(&sector,&mut map64,&mut w64).unwrap();let mut sn=1./(4.*PI).sqrt();for m in 1..=720{sn*=((2*m+1)as f64/(2*m)as f64).sqrt()}let mut maxrel=0_f64;for(r,&theta)in p64.grid().theta().iter().enumerate(){let amp=2.*sn*theta.sin().powi(720);for j in 0..np{let phi=phi0+TAU*j as f64/np as f64;let want=(amp*(720.*phi).cos())as f32;let got=map64[r*np+j]as f32;maxrel=maxrel.max((got as f64-want as f64).abs()/want.abs().max(1e-12)as f64)}}assert!(maxrel<2e-4,"sectoral mode {maxrel}");}
  let analytic_map=map32.clone();let mut out64=vec![Complex64::new(f64::NAN,f64::NAN);spec.nalm()];let input64=analytic_map.iter().map(|&x|x as f64).collect::<Vec<_>>();p64.analysis_into(&input64,&mut out64,&mut w64).unwrap();let got=narrowc(&out64);let mut d=0.;let mut n=0.;let mut mx=0_f64;for(x,y)in got.iter().zip(&a32){let dr=x.re as f64-y.re as f64;let di=x.im as f64-y.im as f64;d+=dr*dr+di*di;n+=y.re as f64*y.re as f64+y.im as f64*y.im as f64;mx=mx.max(dr.hypot(di));}assert!((d/n).sqrt()<1e-4&&mx<2e-5,"scalar analysis analytic");
  let mut analysis_test=vec![Complex32::new(0.,0.);spec.nalm()];let mut analysis_map=vec![0.;nt*np];let analysis_input=(0..nt*np).map(|i|{let i=i as f32;(i*0.000119).cos()-0.3*(i*0.000037).sin()}).collect::<Vec<_>>();p32.analysis_into(&analysis_input,&mut analysis_test,&mut w32).unwrap();p32.adjoint_analysis_into(&a32,&mut analysis_map,&mut w32).unwrap();close(coeff_inner(spec,&analysis_test,&a32),map_inner(&analysis_input,&analysis_map),3e-4,"scalar analysis adjoint");
  println!("SCALAR T720 q={q} m={mmax} synth_analytic_rel_l2={rel:0.3e} synth_max={max:0.3e} analysis_analytic_rel_l2={:0.3e} analysis_max={mx:0.3e} synth_adjoint=PASS analysis_adjoint=PASS sectoral={}",(d/n).sqrt(),if mmax==720{"PASS"}else{"N/A"});
 }}
 spin1_small();edge_checks(std::env::args().nth(1).unwrap().parse().unwrap());
}
fn spin1_small(){let p32=ShtPlan::<f32>::new(GridSpec::new(GridKind::GaussLegendre,2,3,0.23).unwrap(),HarmonicSpec::new(1,1,1).unwrap()).unwrap();let p64=ShtPlan::<f64>::new(GridSpec::new(GridKind::GaussLegendre,2,3,0.23).unwrap(),HarmonicSpec::new(1,1,1).unwrap()).unwrap();let s=p32.harmonics();let mut e=vec![Complex32::new(0.,0.);s.nalm()];let mut b=e.clone();e[s.index(1,0).unwrap()]=Complex32::new(0.26,0.);e[s.index(1,1).unwrap()]=Complex32::new(0.39,-0.07);b[s.index(1,0).unwrap()]=Complex32::new(-0.27,0.);b[s.index(1,1).unwrap()]=Complex32::new(-0.12,0.11);let e64=to64c(&e);let b64=to64c(&b);let(mut x,mut y)=(vec![0.;6],vec![0.;6]);let(mut w64,mut w32)=(p64.workspace().unwrap(),p32.workspace().unwrap());p64.synthesis_spin_into(&e64,&b64,&mut x,&mut y,&mut w64).unwrap();let rx=[-0.2239303440,0.0670698583,-0.0631734356,-0.0006871219,-0.0546924919,-0.1646543145];let ry=[0.1263405234,0.2379926145,-0.1358363330,0.0462721549,0.2390626967,-0.0568380430];for i in 0..6{assert!((x[i]as f32-rx[i]).abs()<2e-6);assert!((y[i]as f32-ry[i]).abs()<2e-6)}let u=(0..6).map(|i|((i as f32)*0.7).sin()).collect::<Vec<_>>();let v=(0..6).map(|i|((i as f32)*0.3).cos()).collect::<Vec<_>>();let mut ae=vec![Complex32::new(0.,0.);s.nalm()];let mut ab=ae.clone();p32.adjoint_synthesis_spin_into(&u,&v,&mut ae,&mut ab,&mut w32).unwrap();let l=x.iter().zip(&u).map(|(&a,&b)|a*b as f64).sum::<f64>()+y.iter().zip(&v).map(|(&a,&b)|a*b as f64).sum::<f64>();let r=coeff_inner(s,&e,&ae)+coeff_inner(s,&b,&ab);close(l,r,3e-5,"spin-1 E/B adjoint");let(mut analyzed_e,mut analyzed_b)=(vec![Complex32::new(0.,0.);s.nalm()],vec![Complex32::new(0.,0.);s.nalm()]);let(mut am1,mut am2)=(vec![0.;6],vec![0.;6]);p32.analysis_spin_into(&u,&v,&mut analyzed_e,&mut analyzed_b,&mut w32).unwrap();p32.adjoint_analysis_spin_into(&e,&b,&mut am1,&mut am2,&mut w32).unwrap();let lhs=coeff_inner(s,&analyzed_e,&e)+coeff_inner(s,&analyzed_b,&b);let rhs=map_inner(&u,&am1)+map_inner(&v,&am2);close(lhs,rhs,5e-5,"spin-1 analysis adjoint");println!("SPIN1 GL 2x3 DUCC E/B-to-Q/U signs=PASS synthesis_adjoint=PASS analysis_adjoint=PASS");}

fn edge_checks(q:usize){
 let nt=721;let np=1458;let n=nt*np;let grid=GridSpec::new(GridKind::GaussLegendre,nt,np,0.23).unwrap();let hs=HarmonicSpec::scalar(720,720).unwrap();let p32=ShtPlan::<f32>::new(grid.clone(),hs.clone()).unwrap();let p64=ShtPlan::<f64>::new(grid,hs.clone()).unwrap();let mut w32=p32.workspace().unwrap();p32.prepare_workspace(&mut w32,q).unwrap();let mut w64=p64.workspace().unwrap();p64.prepare_workspace(&mut w64,q).unwrap();let i00=hs.index(0,0).unwrap();
 for (name,v) in [("zero",0.0_f32),("min_subnormal",f32::from_bits(1)),("min_normal",f32::MIN_POSITIVE),("max_finite",f32::MAX),("infinity",f32::INFINITY),("nan",f32::NAN)]{
  let mut a32=vec![Complex32::new(0.,0.);hs.nalm()];a32[i00].re=v;let a64=to64c(&a32);let mut m32=vec![f32::NAN;n];let mut m64=vec![f64::NAN;n];let rs32=p32.synthesis_into(&a32,&mut m32,&mut w32);let rs64=p64.synthesis_into(&a64,&mut m64,&mut w64);
  if rs32.is_ok()&&rs64.is_ok(){let out64=m64.iter().map(|x|*x as f32).collect::<Vec<_>>();let cm=m32.iter().zip(&out64).filter(|(a,b)|a.is_nan()!=b.is_nan()||a.is_infinite()!=b.is_infinite()||(a.is_infinite()&&b.is_infinite()&&a.is_sign_negative()!=b.is_sign_negative())).count();let fd=m32.iter().zip(&out64).filter(|(a,b)|a.is_finite()&&b.is_finite()&&a.to_bits()!=b.to_bits()).count();let nz0=m32.iter().filter(|x|**x!=0.0).count();let nz1=out64.iter().filter(|x|**x!=0.0).count();println!("EDGE {name} q={q}: synthesis class_mismatch={cm} finite_bit_diff={fd} nonzero_native_adapter={nz0}/{nz1}");}else{println!("EDGE {name} q={q}: synthesis native={:?} adapter={:?}",rs32.as_ref().err(),rs64.as_ref().err());}
  let map32=vec![v;n];let map64=map32.iter().map(|x|*x as f64).collect::<Vec<_>>();let mut c32=vec![Complex32::new(f32::NAN,f32::NAN);hs.nalm()];let mut c64=vec![Complex64::new(f64::NAN,f64::NAN);hs.nalm()];let ra32=p32.analysis_into(&map32,&mut c32,&mut w32);let ra64=p64.analysis_into(&map64,&mut c64,&mut w64);
  if ra32.is_ok()&&ra64.is_ok(){let narrow=narrowc(&c64);let cm=c32.iter().zip(&narrow).filter(|(a,b)|a.re.is_nan()!=b.re.is_nan()||a.im.is_nan()!=b.im.is_nan()||a.re.is_infinite()!=b.re.is_infinite()||a.im.is_infinite()!=b.im.is_infinite()).count();let fd=c32.iter().zip(&narrow).filter(|(a,b)|a.re.is_finite()&&b.re.is_finite()&&a.im.is_finite()&&b.im.is_finite()&&(a.re.to_bits()!=b.re.to_bits()||a.im.to_bits()!=b.im.to_bits())).count();println!("EDGE {name} q={q}: analysis class_mismatch={cm} finite_complex_bit_diff={fd}");}else{println!("EDGE {name} q={q}: analysis native={:?} adapter={:?}",ra32.as_ref().err(),ra64.as_ref().err());}
 }
}
